(async () => {
  const domain = Inputs.Dominio;
  const apiKey = Inputs.ApiKey;
  const auth = Base64.encode(`api:${apiKey}`);

  const params = new URLSearchParams();
  params.append('from', Inputs.From);
  params.append('to', 'k.cordova@macabogados.cl');
  params.append('subject', Inputs.Subject);
  params.append('text', Inputs.Mensaje);
